const row = $input.first().json;
const hasManualAsset = row.pending_asset_id != null;
let niche = null;
if (row.persona_slug === 'backfindr') {
  // persona de marca (mesma Page ID de "geral") — usa o mesmo estilo de conteúdo de geral
  niche = 'geral';
} else if (row.persona_slug && row.persona_slug.startsWith('backfindr-')) {
  niche = row.persona_slug.replace('backfindr-', '');
}
return [{
  json: {
    persona_slug: row.persona_slug,
    product_slug: row.product_slug,
    display_name: row.display_name,
    requires_approval: row.requires_approval,
    default_targets: row.default_targets,
    niche,
    city: 'São Paulo',
