const content = $('Gerar texto do post (GPT-4o-mini)').item.json.choices[0].message.content;
let response;
try {
  response = JSON.parse(content);
} catch (e) {
  response = { texto_post: content, descricao_visual: 'Uma cena urbana realista em ' + $('Selecionar persona e decidir origem').item.json.city };
}
return [{
  json: {
    text: response.texto_post,
    visual_description: response.descricao_visual,
    niche: $('Selecionar persona e decidir origem').item.json.niche,
    city: $('Selecionar persona e decidir origem').item.json.city
  }
}];

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
const b64 = $input.first().json.data[0].b64_json;
const buffer = Buffer.from(b64, 'base64');
const binary = await this.helpers.prepareBinaryData(buffer, 'image.jpg', 'image/jpeg');
const ctx = $('Selecionar persona e decidir origem').item.json;
const assetId = uuidv4();
const category = ctx.niche || 'geral';
const storageKey = ctx.product_slug + '/' + ctx.persona_slug + '/' + category + '/' + assetId + '.jpg';
return [{
  json: {
    asset_id: assetId,
    storage_bucket: 'backfindr-media',
    storage_key: storageKey,
    persona_slug: ctx.persona_slug,
    product_slug: ctx.product_slug,
    display_name: ctx.display_name,
    requires_approval: ctx.requires_approval,
    default_targets: ctx.default_targets,
    category,
    caption: $('Extrair texto e visual').item.json.text,
    source: 'ai:gpt-image-1'
  },
  binary: { image: binary }
}];

